import {
  ClientSession,
  FilterQuery,
  LeanDocument,
  QueryOptions,
  SaveOptions,
  UpdateQuery,
  Model,
} from 'mongoose';

interface FindOptions {
  limit?: number;
  skip?: number;
  select?: any;
  sort?: any;
}

export default class BaseRepository<T> {
  private model: Model<T>;

  constructor(model: Model<T>) {
    this.model = model;
  }

  get = async (id: string, session?: ClientSession): Promise<LeanDocument<T> | null> => {
    const query = this.model.findById(id);
    if (session) {
      query.session(session);
    }
    return query.lean();
  };

  findOne = async (query: FilterQuery<T>, session?: ClientSession): Promise<LeanDocument<T> | null> => {
    const dbQuery = this.model.findOne(query);
    if (session) {
      dbQuery.session(session);
    }
    return dbQuery.lean();
  };

  findById = async (_id: string, session?: ClientSession): Promise<LeanDocument<T> | null> => {
    const query = this.model.findById(_id);
    if (session) {
      query.session(session);
    }
    return query.lean();
  };

  findAll = async (
    filter: FilterQuery<T> = {},
    options: FindOptions = {}
  ): Promise<LeanDocument<T>[]> => {
    const query = this.model.find(filter);
    if (options.limit) query.limit(options.limit);
    if (options.skip) query.skip(options.skip);
    if (options.select) query.select(options.select);
    if (options.sort) query.sort(options.sort);
    return query.lean();
  };

  save = async (data: Partial<T>, options: SaveOptions = {}): Promise<LeanDocument<T>> => {
    const instance = new this.model(data);
    return (await instance.save(options)).toObject();
  };

  update = async (
    query: FilterQuery<T>,
    data: Partial<T> | UpdateQuery<T>,
    options: QueryOptions = { new: true }
  ): Promise<LeanDocument<T> | null> => {
    return this.model.findOneAndUpdate(query, data, options).lean();
  };

  delete = async (query: FilterQuery<T>, options: QueryOptions = {}): Promise<void> => {
    await this.model.deleteOne(query, options);
  };

  deleteMany = async (query: FilterQuery<T>, options: QueryOptions = {}): Promise<void> => {
    await this.model.deleteMany(query, options);
  };

  updateMany = async (
    query: FilterQuery<T>,
    data: Partial<T> | UpdateQuery<T>,
    options: QueryOptions = {}
  ): Promise<any> => {
    return await this.model.updateMany(query, data, options);
  };

  findMany = (filter: FilterQuery<T>, projection?: any) => {
    return this.model.find(filter, projection);
  };
}

export interface CustomError extends Error {
  status?: number;
  code?: number | string;
  saveInDB?: boolean;
}

export interface AppErrorArgs {
  status?: number;
  code?: number | string;
  message: string;
  saveInDB?: boolean;
}

export class AppError extends Error implements CustomError {
  status?: number;
  code?: number | string;
  saveInDB?: boolean;

  constructor(args: AppErrorArgs) {
    super(args.message);
    this.status = args.status ?? 500;
    this.code = args.code;
    this.saveInDB = args.saveInDB ?? false;
    this.name = 'AppError';
    Error.captureStackTrace(this, this.constructor);
  }
}

export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  message?: string;
  error?: {
    code: number;
    message: string;
    errorCode?: number | string;
  };
}

export interface PaginatedResponse<T = any> extends ApiResponse<T[]> {
  pagination?: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

import { Request, Response, NextFunction } from 'express';
import logger from '@/services/logger';

// For controller methods
export const catchAsync = (
  fn: (req: Request, res: Response, next: NextFunction) => Promise<any>
) => {
  return (req: Request, res: Response, next: NextFunction) => {
    fn(req, res, next).catch(next);
  };
};

// For functions
export const wrapAsync = <T extends (...args: any[]) => Promise<any>>(
  fn: T
): T => {
  return ((...args: any[]) => {
    return fn(...args).catch((err: any) => {
      // Centralized error handling
      logger.error(`Async error: ${err.message}`, { code: err.code });
      throw err;
    });
  }) as T;
};

// Mongo duplicate-key errors (unique index violations). Single writes carry
// code 11000 directly; bulk writes (insertMany) nest them inside writeErrors.
export const isDuplicateKeyError = (error: unknown): boolean => {
  const err = error as { code?: unknown; writeErrors?: Array<{ code?: unknown }> };
  if (err?.code === 11000) {
    return true;
  }
  return Array.isArray(err?.writeErrors) && err.writeErrors.some((e) => e?.code === 11000);
};

