    typeof a.resourceId !== 'string' || !/^[a-f0-9]{24}$/.test(a.resourceId) || typeof a.identityKey !== 'string' || !opaque(a.sourceDocumentReference) ||
    !['owned_upload', 'labstack', 'healthians', 'legacy_import'].includes(a.sourceSystem) ||
    !['private_attachment', 'clinical_document', 'public_image'].includes(a.purpose) || a.identityKey !== assetKey(a) ||
    a._id.toHexString() !== a.identityKey.slice(0, 24) || !Number.isSafeInteger(a.revision) || a.revision < 0 ||
    !(a.createdAt instanceof Date) || !Number.isFinite(a.createdAt.getTime()) || a.createdByUserId !== a.ownerUserId ||
    (a.revokedAt !== null && (!(a.revokedAt instanceof Date) || !Number.isFinite(a.revokedAt.getTime()))) ||
    ![a.currentCapturedVersionId, a.currentReadableVersionId].every(id => id === null || id instanceof Types.ObjectId) ||
    (a.resourceKind === 'unbound_upload') !== (a.purpose === 'private_attachment') ||
    (a.resourceKind === 'unbound_upload' && a.resourceId !== a.ownerUserId)) throw documentError();
}
export function assertVersion(a: FileAsset, v: FileVersion): void {
  if (!v || !(v._id instanceof Types.ObjectId) || !(v.assetId instanceof Types.ObjectId) || !v.assetId.equals(a._id) ||
    v.identityKey !== a.identityKey || typeof v.storageKey !== 'string' || typeof v.versionKey !== 'string' ||
    typeof v.contentSha256 !== 'string' || !/^[a-f0-9]{64}$/.test(v.contentSha256) || !Number.isSafeInteger(v.actualSize) ||
    v.actualSize < 1 || v.actualSize > DOCUMENT_BYTES || !['application/pdf', 'image/jpeg', 'image/png', 'image/webp'].includes(v.mediaType) ||
    v.sourceSystem !== a.sourceSystem || v.sourceDocumentReference !== a.sourceDocumentReference || v.createdByUserId !== a.ownerUserId ||
    !['preliminary', 'final', 'unknown'].includes(v.completeness) || !(v.capturedAt instanceof Date) || !Number.isFinite(v.capturedAt.getTime()) ||
    !(v.amendsVersionId === null || v.amendsVersionId instanceof Types.ObjectId) || !(v.amendmentReason === null || opaque(v.amendmentReason)) ||
    !Number.isSafeInteger(v.stateRevision) || v.stateRevision < 0 || v.versionKey !== versionKey(v) ||
    !v.validation || !['quarantined', 'validated', 'rejected'].includes(v.validation.state) ||
    (v.validation.state === 'quarantined' && v.validation.evidenceRef !== null) ||
    !v.publication || !['unreleased', 'released', 'legacy_access_unknown'].includes(v.publication.state) ||
    (v.publication.state === 'unreleased' && v.publication.evidenceRef !== null) ||
    (v.validation.state !== 'quarantined' && !opaque(v.validation.evidenceRef)) ||
    (v.publication.state !== 'unreleased' && !opaque(v.publication.evidenceRef)) ||
    !new RegExp('^' + a._id.toHexString() + '/' + v._id.toHexString() + '/[a-f0-9]{64}$').test(v.storageKey)) throw documentError();
}
export function readable(a: FileAsset, v: FileVersion): boolean {
  return a.revokedAt === null && v.validation.state === 'validated' &&
    ((a.purpose === 'private_attachment' && a.resourceKind === 'unbound_upload' && v.publication.state === 'unreleased') ||
     (a.purpose === 'clinical_document' && v.publication.state === 'released'));
}
export function dto(a: FileAsset, v: FileVersion): VersionDTO {
  assertAsset(a); assertVersion(a, v);
  return { assetId: a._id.toHexString(), versionId: v._id.toHexString(), resourceKind: a.resourceKind, resourceId: a.resourceId,
    purpose: a.purpose, mediaType: v.mediaType, byteLength: v.actualSize, capturedAt: v.capturedAt.toISOString(),
    completeness: v.completeness, validationState: v.validation.state, publicationState: v.publication.state,
    isCurrentReadable: a.currentReadableVersionId?.equals(v._id) === true,
    contentUrl: readable(a, v) ? `/api/v1/file/assets/${a._id.toHexString()}/versions/${v._id.toHexString()}/content` : null };
}

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { CONFIG } from '@/config/config';
import { AppError } from '@/modules/common/types';
import PharmacyModel from '@/modules/pharmacies/model';

export interface AuthRequest extends Request {
  user?: {
    _id: string;
    phone?: string;
    email?: string;
    corporateId?: string;
    specialistId?: string;
    pharmacyId?: string;
    userType: string;
  };
}

const decodeAuthToken = (authHeader?: string): AuthRequest['user'] | null => {
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return null;
  }

  const token = authHeader.substring(7);
  const decoded = jwt.verify(token, CONFIG.JWT_SECRET_KEY) as AuthRequest['user'];
  return decoded;
};

export const authenticate = (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): void => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      throw new AppError({
        status: 401,
        code: 'UNAUTHORIZED',
        message: 'Authorization token is required',
      });
    }

    try {
      req.user = decodeAuthToken(authHeader) || undefined;
      next();
    } catch (error: any) {
      if (error.name === 'TokenExpiredError') {
        throw new AppError({
          status: 401,
          code: 'TOKEN_EXPIRED',
          message: 'Token has expired',
        });
      } else if (error.name === 'JsonWebTokenError') {
        throw new AppError({
          status: 401,
          code: 'INVALID_TOKEN',
          message: 'Invalid token',
        });
      }
      throw error;
    }
  } catch (error) {
    next(error);
  }
};

export const authenticateOptional = (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): void => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader) {
      next();
      return;
    }

    req.user = decodeAuthToken(authHeader) || undefined;
    next();
  } catch (error) {
    next(error);
  }
};

export const requireAdmin = (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): void => {
  try {
    if (!req.user) {
      throw new AppError({
        status: 401,
        code: 'UNAUTHORIZED',
        message: 'Authentication is required',
      });
    }

    if (req.user.userType !== 'admin') {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Admin access is required',
      });
    }

    next();
  } catch (error) {
    next(error);
  }
};

export const requireHR = (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): void => {
  try {
    if (!req.user) {
      throw new AppError({
        status: 401,
        code: 'UNAUTHORIZED',
        message: 'Authentication is required',
      });
    }

    if (req.user.userType !== 'hr') {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'HR access is required',
      });
    }

    if (!req.user.corporateId) {
      throw new AppError({
        status: 403,
        code: 'HR_CORPORATE_REQUIRED',
        message: 'HR account must be linked to a corporate',
      });
    }

    next();
  } catch (error) {
    next(error);
  }
};

export const requireAdminOrHR = (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): void => {
  try {
    if (!req.user) {
      throw new AppError({
        status: 401,
        code: 'UNAUTHORIZED',
        message: 'Authentication is required',
      });
    }

    if (req.user.userType !== 'admin' && req.user.userType !== 'hr') {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Admin or HR access is required',
      });
    }

    if (req.user.userType === 'hr' && !req.user.corporateId) {
      throw new AppError({
        status: 403,
        code: 'HR_CORPORATE_REQUIRED',
        message: 'HR account must be linked to a corporate',
      });
    }

    next();
  } catch (error) {
    next(error);
  }
};

export const requireSpecialist = (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): void => {
  try {
    if (!req.user) {
      throw new AppError({
        status: 401,
        code: 'UNAUTHORIZED',
        message: 'Authentication is required',
      });
    }

    if (req.user.userType !== 'specialist') {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Specialist access is required',
      });
    }

    const specialistId = req.user.specialistId || req.user._id;
    if (!specialistId) {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Specialist access is required',
      });
    }

    req.user.specialistId = specialistId;
    next();
  } catch (error) {
    next(error);
  }
};

export const requirePharmacy = (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): void => {
  try {
    if (!req.user) {
      throw new AppError({
        status: 401,
        code: 'UNAUTHORIZED',
        message: 'Authentication is required',
      });
    }

    if (req.user.userType !== 'pharmacy') {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Pharmacy access is required',
      });
    }

    const pharmacyId = req.user.pharmacyId || req.user._id;
    if (!pharmacyId) {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Pharmacy account must be linked to a pharmacy profile',
      });
    }

    req.user.pharmacyId = pharmacyId;
    next();
  } catch (error) {
    next(error);
  }
};

export const requireAdminOrPharmacy = (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): void => {
  try {
    if (!req.user) {
      throw new AppError({
        status: 401,
        code: 'UNAUTHORIZED',
        message: 'Authentication is required',
      });
    }

    if (req.user.userType === 'admin') {
      return next();
    }

    if (req.user.userType === 'pharmacy') {
      const pharmacyId = req.user.pharmacyId || req.user._id;
      if (!pharmacyId) {
        throw new AppError({
          status: 403,
          code: 'FORBIDDEN',
          message: 'Pharmacy account must be linked to a pharmacy profile',
        });
      }

      req.user.pharmacyId = pharmacyId;
      return next();
    }

    throw new AppError({
      status: 403,
      code: 'FORBIDDEN',
      message: 'Admin or pharmacy access is required',
    });
  } catch (error) {
    next(error);
  }
};

const assertOperationalPharmacy = async (req: AuthRequest): Promise<void> => {
  const pharmacyId = req.user?.pharmacyId || req.user?._id;
  if (!pharmacyId) {
    throw new AppError({
      status: 403,
      code: 'PHARMACY_PROFILE_REQUIRED',
      message: 'Pharmacy account must be linked to a pharmacy profile',
    });
  }

  const pharmacy = await PharmacyModel.findById(pharmacyId)
    .select('_id isActive isVerified archivedAt')
    .lean();

  if (!pharmacy || pharmacy.archivedAt || pharmacy.isActive === false) {
    throw new AppError({
      status: 403,
      code: 'PHARMACY_INACTIVE',
      message: 'This pharmacy account is inactive',
    });
  }

  if (!pharmacy.isVerified) {
    throw new AppError({
      status: 403,
      code: 'PHARMACY_NOT_VERIFIED',
      message: 'Pharmacy verification is required for this operation',
    });
  }

  req.user!.pharmacyId = String(pharmacy._id);
};

/** Pharmacy business operations use this; onboarding/profile routes use requirePharmacy. */
export const requireOperationalPharmacy = async (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): Promise<void> => {
  try {
    if (!req.user) {
      throw new AppError({ status: 401, code: 'UNAUTHORIZED', message: 'Authentication is required' });
    }
    if (req.user.userType !== 'pharmacy') {
      throw new AppError({ status: 403, code: 'FORBIDDEN', message: 'Pharmacy access is required' });
    }
    await assertOperationalPharmacy(req);
    next();
  } catch (error) {
    next(error);
  }
};

export const requireAdminOrOperationalPharmacy = async (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): Promise<void> => {
  try {
    if (!req.user) {
      throw new AppError({ status: 401, code: 'UNAUTHORIZED', message: 'Authentication is required' });
    }
    if (req.user.userType === 'admin') {
      next();
      return;
    }
    if (req.user.userType !== 'pharmacy') {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Admin or verified pharmacy access is required',
      });
    }
    await assertOperationalPharmacy(req);
    next();
  } catch (error) {
    next(error);
  }
};

import { Request, Response, NextFunction } from 'express';
import { CustomError } from '@/modules/common/types';
import logger from '@/services/logger';
import { isDuplicateKeyError } from '@/modules/common/utils/mongoErrors';

export const errorHandler = (
  err: CustomError,
  _req: Request,
  res: Response,
  _next: NextFunction
) => {
  // TODO: here add logger.error
  logger.error(err.message, {});

  if (isDuplicateKeyError(err)) {
    return res.status(409).json({
      error: 409,
      message: 'This record already exists. Please refresh and try again.',
      code: 'DUPLICATE_RESOURCE',
    });
  }

  // if no status or message in error use default 500 code and message
  const statusCode = err.status ?? 500;
  const message = err.message || 'Something went wrong.';

  // returns error status code and message
  return res.status(statusCode).json({
    error: statusCode,
    message: message,
    code: err?.code,
  });
};

